const japanArmedLandscape={src:"assets/diagrams/postwar-japanese-armed-forces.svg",alt:"Institutional relationship among the Emperor, Cabinet, Imperial Defense Council, Army, Navy, integral regions, and associated-state forces",caption:"Japan preserves separate armed services while Cabinet, imperial councils, common registers, and treaty relationships coordinate their work"};
